/**
 * Quick test to debug beacon CRC issues
 */

import { encodeBeacon, parseBeacon, type BeaconMeta } from './src/core/frame/beacon.js';

function createValidMeta(): BeaconMeta {
  return {
    streamId: 0x12345678,
    wireVersion: 1,
    originalSize: 1024 * 1024, // 1 MB
    payloadLen: 1024 * 1024, // 1 MB (uncompressed)
    blockSize: 192 * 1024, // 192 KB
    blockCount: 6,
    fragmentLen: 256, // L
    degreeCap: 64,
    flags: 0,
    blockHashLen: 4,
    wholeFileHash: new Uint8Array(32), // All zeros for testing
    manifestHash: new Uint8Array(4), // CRC-32 of manifest
    filename: 'test.txt',
    mimeType: 'text/plain',
  };
}

function createBeaconWithBlockSize(blockSize: number): Uint8Array {
  const meta = createValidMeta();
  // Keep values consistent
  const calculatedSize = meta.blockCount * blockSize;
  meta.originalSize = calculatedSize;
  meta.payloadLen = calculatedSize;
  meta.blockSize = blockSize;
  return encodeBeacon(meta);
}

// Test with blockSize that should work
console.log('Testing with blockSize = 192 * 1024 (should work)...');
const encoded1 = createBeaconWithBlockSize(192 * 1024);
console.log('Encoded beacon length:', encoded1.length);

try {
  const parsed1 = parseBeacon(encoded1, 768, 10 * 1024 * 1024);
  console.log('✓ Successfully parsed beacon with blockSize=192KB');
  console.log('  Parsed blockSize:', parsed1.blockSize);
} catch (error) {
  console.error('✗ Failed to parse beacon with blockSize=192KB');
  console.error('  Error code:', error.code);
  console.error('  Error message:', error.message);
}

// Test with larger blockSize that should fail K validation
console.log('\nTesting with blockSize = 200 * 1024 (should fail K validation)...');
const encoded2 = createBeaconWithBlockSize(200 * 1024);
console.log('Encoded beacon length:', encoded2.length);

try {
  const parsed2 = parseBeacon(encoded2, 768, 10 * 1024 * 1024);
  console.log('✓ Successfully parsed beacon with blockSize=200KB (unexpected!)');
  console.log('  Parsed blockSize:', parsed2.blockSize);
} catch (error) {
  console.error('✗ Failed to parse beacon with blockSize=200KB');
  console.error('  Error code:', error.code);
  console.error('  Error message:', error.message);
  if (error.code === 'E-K-OVERFLOW') {
    console.log('  ✓ Got expected K-OVERFLOW error');
  } else {
    console.log('  ✗ Got unexpected error code (expected E-K-OVERFLOW)');
  }
}

